  "source": "pragma cashscript ^0.14.0;\n\n// =====================================================================================\n// Evermore SaleToken: one listing (a hero or a gear NFT) priced in a fungible CashToken,\n// used for ParyonUSD (PUSD) so a seller can ask a dollar price and be paid in dollars.\n// No operator, no game logic. The address is derived from (sellerPkh, price, payCategory);\n// the listing tx carries an OP_RETURN 'EVR2' sellerPkh price8 so clients find it and\n// rebuild this address (payCategory is the game's PUSD category).\n//\n// buy(): the output at THIS input's index pays the seller at least `price` units of the\n//   payCategory token (PUSD has 2 decimals: 150 = $1.50), and nothing else as a token.\n//   The NFT goes wherever the buyer puts it, in the same transaction (atomic swap).\n//   Stops: underpaying, paying someone else, paying in another token or in plain BCH,\n//   and settling two listings with one payment (each needs its own output at its index).\n// cancel(): the seller signs (pubkey must hash to sellerPkh).\n// =====================================================================================\ncontract SaleToken(bytes20 sellerPkh, int price, bytes32 payCategory) {\n    function buy() {\n        int i = this.activeInputIndex;\n        require(tx.outputs[i].lockingBytecode == new LockingBytecodeP2PKH(sellerPkh));\n        // the category must match; the amount must cover the price\n        require(tx.outputs[i].tokenCategory == payCategory);\n        require(tx.outputs[i].tokenAmount >= price);\n    }\n\n    function cancel(pubkey pk, sig s) {\n        require(hash160(pk) == sellerPkh);\n        require(checkSig(s, pk));\n    }\n}\n",
